# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUR\'AN OKUMAYA GİRİŞ: HAREKELER (ÜSTÜN - ESRE - ÖTRE)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Üstün (Fetha)</text>\n  <text x="125" y="108" text-anchor="middle" font-size="22" font-weight="bold" fill="#1e3a8a">كَ - تَ - بَ</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" fill="#334155">Harfin üstüne konulan yatay çizgi.</text>\n  <text x="125" y="160" text-anchor="middle" font-size="11" fill="#334155">İnce harfleri \'e\', kalınları \'a\' okutur.</text>\n  <text x="125" y="195" text-anchor="middle" font-size="15" font-weight="bold" fill="#2563eb">كَتَبَ (Ketebe)</text>\n  <text x="125" y="218" text-anchor="middle" font-size="12" fill="#1e40af">خَلَقَ (Halaka)</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Esre (Kesra)</text>\n  <text x="350" y="108" text-anchor="middle" font-size="22" font-weight="bold" fill="#14532d">عَ - لِ - مَ</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" fill="#334155">Harfin altına konulan yatay çizgi.</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#334155">İnce harfleri \'i\', kalınları \'ı-i\' okutur.</text>\n  <text x="350" y="195" text-anchor="middle" font-size="15" font-weight="bold" fill="#16a34a">عَلِمَ (Alime)</text>\n  <text x="350" y="218" text-anchor="middle" font-size="12" fill="#166534">سَمِعَ (Semi\'a)</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#a16207">Ötre (Damme)</text>\n  <text x="575" y="108" text-anchor="middle" font-size="22" font-weight="bold" fill="#713f12">حَ - سُ - نَ</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" fill="#334155">Harfin üstüne konulan küçük vav.</text>\n  <text x="575" y="160" text-anchor="middle" font-size="11" fill="#334155">İnce harfleri \'ü-u\', kalınları \'u\' okutur.</text>\n  <text x="575" y="195" text-anchor="middle" font-size="15" font-weight="bold" fill="#ca8a04">حَسُنَ (Hasüne)</text>\n  <text x="575" y="218" text-anchor="middle" font-size="12" fill="#854d0e">رُسُلُ (Rusülü)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CEZİM (SÜKÛN) VE ŞEDDE İLE OKUNUŞ KURALLARI</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#7e22ce">Cezim (Sükûn) İşareti ( ْ )</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11" fill="#334155">Harfin üzerine konulan küçük daire işaretidir.</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11" fill="#334155">Üzerinde cezim olan harf harekesizdir; kendinden</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11" fill="#334155">önceki harekeli harfe tutunarak tek hecede okunur.</text>\n  <text x="180" y="168" text-anchor="middle" font-size="16" font-weight="bold" fill="#6b21a8">مِنْ (Min)  |  عَنْ (An)  |  لَمْ (Lem)</text>\n  <text x="180" y="198" text-anchor="middle" font-size="15" font-weight="bold" fill="#7e22ce">يَكْتُبُ (Yek-tü-bü)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="12" fill="#475569">اَلْحَمْدُ (El-ham-dü)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#be123c">Şedde İşareti ( ّ )</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11" fill="#334155">Harfin üzerine konulan dişli (w benzeri) işarettir.</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11" fill="#334155">Yan yana gelen iki aynı harften birincisi cezimli,</text>\n  <text x="520" y="136" text-anchor="middle" font-size="11" fill="#334155">ikincisi harekeli olduğunda tek harfte birleştirilir.</text>\n  <text x="520" y="168" text-anchor="middle" font-size="15" font-weight="bold" fill="#9f1239">رَبْ + بَ = رَبَّ (Rab-be)</text>\n  <text x="520" y="198" text-anchor="middle" font-size="15" font-weight="bold" fill="#be123c">عَلَّمَ (Al-le-me)  |  إِنَّ (İn-ne)</text>\n  <text x="520" y="220" text-anchor="middle" font-size="12" fill="#475569">مُحَمَّدٌ (Mu-ham-me-dün)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜBHANEKE VE RABBENA DUALARINDA HAREKE-CEZİM-ŞEDDE UYGULAMASI</text>\n  <rect x="25" y="48" width="650" height="90" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Sübhaneke Duasından Örnek Kelime Çözümlemeleri</text>\n  <text x="350" y="100" text-anchor="middle" font-size="15" font-weight="bold" fill="#155e75">سُبْحَانَكَ (Süb-hâ-ne-ke)  •  اللَّهُمَّ (Al-lâ-hüm-me)  •  وَبِحَمْدِكَ (Ve bi-ham-di-ke)</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11" fill="#334155">سُبْحَانَكَ kelimesinde بْ harfi cezimli; اللَّهُمَّ kelimesinde لَّ ve مَّ harfleri şeddelidir.</text>\n\n  <rect x="25" y="150" width="650" height="90" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Rabbena Dualarından Örnek Kelime Çözümlemeleri</text>\n  <text x="350" y="202" text-anchor="middle" font-size="15" font-weight="bold" fill="#78350f">رَبَّنَا (Rab-be-nâ)  •  الدُّنْيَا (Ed-dün-yâ)  •  اغْفِرْ لِي (İğ-fir lî)  •  الْحِسَابُ (El-hi-sâ-bü)</text>\n  <text x="350" y="226" text-anchor="middle" font-size="11" fill="#334155">رَبَّنَا kelimesinde بَّ şeddeli; الدُّنْيَا kelimesinde دُّ şeddeli ve نْ cezimli olarak okunur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
